import{_ as t,c as a,o,ae as n}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Getting Started with buddyGenAI (Web version)","description":"","frontmatter":{},"headers":[],"relativePath":"web-setup.md","filePath":"web-setup.md"}'),i={name:"web-setup.md"};function r(s,e,h,d,l,c){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="getting-started-with-buddygenai-web-version" tabindex="-1">Getting Started with buddyGenAI (Web version) <a class="header-anchor" href="#getting-started-with-buddygenai-web-version" aria-label="Permalink to &quot;Getting Started with buddyGenAI (Web version)&quot;">​</a></h1><p>This guide will walk you through the process of to setting up buddyGenAI to be able to chat, generate images and speech, as well as the option to use voice input instead of typing messages.</p><p>buddyGenAI is designed for you to Bring Your Own AI, which this guide should help you with.</p><h2 id="ai-provider-compatibility" tabindex="-1">AI Provider Compatibility <a class="header-anchor" href="#ai-provider-compatibility" aria-label="Permalink to &quot;AI Provider Compatibility&quot;">​</a></h2><p>To use the core of the app, you&#39;ll need to setup at least <strong>chat AI</strong>, which currently supports choosing 1 from 3 providers:</p><ul><li><a href="https://github.com/LostRuins/koboldcpp" target="_blank" rel="noreferrer"><strong>KoboldCpp</strong></a> (Chat / Image / TTS / Transcription): Supports <a href="https://github.com/LostRuins/koboldcpp#windows-usage-precompiled-binary-recommended" target="_blank" rel="noreferrer">Windows</a>, <a href="https://github.com/LostRuins/koboldcpp#macos-precompiled-binary" target="_blank" rel="noreferrer">Mac</a> and <a href="https://github.com/LostRuins/koboldcpp#linux-usage-precompiled-binary-recommended" target="_blank" rel="noreferrer">Linux</a></li><li><a href="https://webllm.mlc.ai/" target="_blank" rel="noreferrer"><strong>WebLLM</strong></a> (Chat only): Run chat models within your browser (supports Chrome-like browsers)</li><li><a href="https://openrouter.ai/" target="_blank" rel="noreferrer"><strong>OpenRouter</strong></a> (Chat only): If you can&#39;t run models on your own hardware, this is less private but provides an alternate option to use the app. Requires signing up and managing payment info with OpenRouter.</li></ul><h2 id="installation-and-setup" tabindex="-1">Installation and Setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and Setup&quot;">​</a></h2><p>(<em>Sorry this is incomplete - I ran out of steam in the middle of writing this.</em>)</p><h2 id="chatting" tabindex="-1">Chatting <a class="header-anchor" href="#chatting" aria-label="Permalink to &quot;Chatting&quot;">​</a></h2><p>After creating a buddy, you&#39;ll be taken to a new chat with them. To create a new chat, go to the Chat tab and select a buddy from the dropdown to the right of the <code>Chat with:</code> label.</p><h3 id="text-to-speech" tabindex="-1">Text-to-Speech <a class="header-anchor" href="#text-to-speech" aria-label="Permalink to &quot;Text-to-Speech&quot;">​</a></h3><p>If you&#39;ve imported TTS voice(s) then you can click the speaker icon on AI messages to have them spoken out loud. You can set buddies to have a specific voice by going to the buddy&#39;s Edit page.</p><p>You can have message auto-speak by going to the Settings tab -&gt; <code>Text-to-Speech Options</code> and enabling the option &quot;Auto Read Chat&quot;.</p><h3 id="voice-input-transcription" tabindex="-1">Voice Input / Transcription <a class="header-anchor" href="#voice-input-transcription" aria-label="Permalink to &quot;Voice Input / Transcription&quot;">​</a></h3><p>If you&#39;ve imported an STT model, you can click the microphone icon in the chat input, speak your message and click the microphone icon again to have your speech converted to text.</p><div class="note custom-block github-alert"><p class="custom-block-title">Want to save a click?</p><p></p><p>You can automatically send messages after transcription by going to <code>Options</code> -&gt; <code>Voice</code> -&gt; <code>Transcription</code> and enabling the option <strong>Auto-Send after recording</strong>.</p><p>With this enabled, clicking the Stop Recording button will automatically send your message once the audio is transcribed.</p></div><h3 id="enable-ai-sent-chat-images" tabindex="-1">Enable (AI-sent) Chat Images <a class="header-anchor" href="#enable-ai-sent-chat-images" aria-label="Permalink to &quot;Enable (AI-sent) Chat Images&quot;">​</a></h3><p>Chat images are disabled by default. To enable them, go to <code>Options</code> -&gt; <code>Experimental</code> and then click &quot;Enable Chat Images&quot; and optionally change the quality dropdown under it, which will affect the quality and speed of the images generated.</p><p>With the option enabled, any AI in the app may generate and send images based on the chat&#39;s context.</p><h3 id="changing-models" tabindex="-1">Changing Models <a class="header-anchor" href="#changing-models" aria-label="Permalink to &quot;Changing Models&quot;">​</a></h3><p>You may change and import AI models by going to the Settings tab.</p><p>Note that if you change the chat model then you&#39;ll need to restart the app or use the in-app control to restart the chat model (through the Chat tab -&gt; click &quot;Chat Online&quot;).</p>',22)]))}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
